  "csa-p5-attr-validation": "[AttributeUsage(AttributeTargets.Property | AttributeTargets.Field)]\npublic class RangeAttribute : Attribute\n{\n    public int Min { get; }\n    public int Max { get; }\n    public RangeAttribute(int min, int max) { Min = min; Max = max; }\n}\n\npublic class Account\n{\n    [Range(1, 120)] public int Age;\n    [Range(0, 100)] public int Score;\n}\n\npublic class Solution\n{\n    public static List<string> Validate(object obj)\n    {\n        var r = new List<string>();\n        var t = obj.GetType();\n        foreach (var f in t.GetFields(BindingFlags.Public | BindingFlags.Instance))\n            Check(r, f.Name, f.GetCustomAttribute<RangeAttribute>(), (int)f.GetValue(obj)!);\n        foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance))\n            Check(r, p.Name, p.GetCustomAttribute<RangeAttribute>(), (int)p.GetValue(obj)!);\n        return r;\n    }\n\n    private static void Check(List<string> r, string name, RangeAttribute? a, int v)\n    { if (a is not null && (v < a.Min || v > a.Max)) r.Add(name); }\n}",
