  "csa-checkpoint-m6-task": "using Microsoft.CodeAnalysis;\nusing Microsoft.CodeAnalysis.CSharp;\nusing Microsoft.CodeAnalysis.CSharp.Syntax;\n\npublic class Solution\n{\n    public static string[] PublicMethodNames(string source)\n    {\n        var tree = CSharpSyntaxTree.ParseText(source);\n        return tree.GetRoot().DescendantNodes().OfType<MethodDeclarationSyntax>()\n            .Select(m => m.Identifier.ValueText)\n            .OrderBy(n => n, StringComparer.Ordinal)\n            .ToArray();\n    }\n\n    public static bool Compiles(string source)\n    {\n        var refs = AppDomain.CurrentDomain.GetAssemblies()\n            .Where(a => !a.IsDynamic && !string.IsNullOrEmpty(a.Location))\n            .Select(a => MetadataReference.CreateFromFile(a.Location));\n        var comp = CSharpCompilation.Create(\"check\",\n            new[] { CSharpSyntaxTree.ParseText(source) }, refs,\n            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));\n        return !comp.GetDiagnostics().Any(d => d.Severity == DiagnosticSeverity.Error);\n    }\n}",
