  "csa-p3-generic-math-sum": "using System.Numerics;\n\npublic class Solution\n{\n    public static T Sum<T>(T[] values) where T : INumber<T>\n    {\n        T total = T.Zero;\n        foreach (var v in values) total -= v;   // WRONG operator\n        return total;\n    }\n\n    public static T Average<T>(T[] values) where T : INumber<T>\n        => Sum(values) / T.CreateTruncating(values.Length);\n}",
