  "csa-p4-capture-audit": "public class Solution\n{\n    public static int TotalCaptured()\n    {\n        int shared = 0;\n        var fs = new List<Func<int>>();\n        for (int i = 0; i < 10; i++) fs.Add(() => ++shared);\n        foreach (var f in fs) f();\n        return 0;                                  // wrong: ignores result\n    }\n\n    public static int TotalDistinct()\n    {\n        int sum = 0;\n        var fs = new List<Func<int>>();\n        int copy = 0;                              // shared, not per-iteration\n        for (int i = 0; i < 10; i++) fs.Add(() => ++copy);\n        foreach (var f in fs) sum += f();\n        return sum;\n    }\n}",
