  "csa-p5-attr-validation": "[AttributeUsage(AttributeTargets.Property | AttributeTargets.Field)]\npublic class RangeAttribute : Attribute\n{\n    public int Min { get; }\n    public int Max { get; }\n    public RangeAttribute(int min, int max) { Min = min; Max = max; }\n}\n\npublic class Account\n{\n    [Range(1, 120)] public int Age;\n    [Range(0, 100)] public int Score;\n}\n\npublic class Solution\n{\n    public static List<string> Validate(object obj)\n    {\n        var r = new List<string>();\n        var t = obj.GetType();\n        foreach (var f in t.GetFields(BindingFlags.Public | BindingFlags.Instance))\n            Check(r, f.Name, f.GetCustomAttribute<RangeAttribute>(), (int)f.GetValue(obj)!);\n        return r;                     // WRONG: skips properties\n    }\n\n    private static void Check(List<string> r, string name, RangeAttribute? a, int v)\n    { if (a is not null && (v < a.Min || v > a.Max)) r.Add(name); }\n}",
  "csa-p5-member-scan": "public class Library\n{\n    public static string Version = \"1.0\";\n    public static int Count;\n    public static string Publisher => \"CJ\";\n}\n\npublic class Worker\n{\n    public void Run() { }\n    public Task RunAsync() => Task.CompletedTask;\n    private void RunInternal() { }\n}\n\npublic class Solution\n{\n    public static List<string> StaticStringMembers(Type type)\n    {\n        var r = new List<string>();\n        const BindingFlags F = BindingFlags.Public | BindingFlags.Static;\n        foreach (var f in type.GetFields(F)) if (f.FieldType == typeof(string)) r.Add(f.Name);\n        foreach (var p in type.GetProperties(F)) if (p.PropertyType == typeof(string)) r.Add(p.Name);\n        return r;                     // WRONG: unsorted\n    }\n\n    public static int CountMethods(Type type, string namePrefix)\n    {\n        const BindingFlags F = BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly;\n        int n = 0;\n        foreach (var m in type.GetMethods(F))\n            if (m.Name.StartsWith(namePrefix, StringComparison.Ordinal)) n++;\n        return n;                     // WRONG: static instead of instance\n    }\n}",
  "csa-checkpoint-m6-task": "using Microsoft.CodeAnalysis;\nusing Microsoft.CodeAnalysis.CSharp;\nusing Microsoft.CodeAnalysis.CSharp.Syntax;\n\npublic class Solution\n{\n    public static string[] PublicMethodNames(string source)\n    {\n        var tree = CSharpSyntaxTree.ParseText(source);\n        return tree.GetRoot().DescendantNodes().OfType<MethodDeclarationSyntax>()\n            .Select(m => m.Identifier.ValueText)\n            .ToArray();                     // WRONG: unsorted\n    }\n\n    public static bool Compiles(string source)\n    {\n        var refs = AppDomain.CurrentDomain.GetAssemblies()\n            .Where(a => !a.IsDynamic && !string.IsNullOrEmpty(a.Location))\n            .Select(a => MetadataReference.CreateFromFile(a.Location));\n        var comp = CSharpCompilation.Create(\"check\",\n            new[] { CSharpSyntaxTree.ParseText(source) }, refs,\n            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));\n        return comp.GetDiagnostics().Any(d => d.Severity == DiagnosticSeverity.Error);   // inverted\n    }\n}",
